-- One row for each version of the contract terms of a user. A version
-- applies from the local calendar date valid_from in the time zone of the
-- user. The service needs at least one version for each user_settings row.
-- lock_timeout makes a busy user_settings table fail the migrate step.
-- Do not edit this file after release: SQLx checks its hash.
SET LOCAL lock_timeout = '5s';

CREATE TABLE contract_terms (
  user_id TEXT NOT NULL REFERENCES user_settings (user_id) ON DELETE CASCADE,
  valid_from DATE NOT NULL,
  margin_cents_kwh DOUBLE PRECISION NOT NULL,
  transfer_day_cents_kwh DOUBLE PRECISION NOT NULL,
  transfer_night_cents_kwh DOUBLE PRECISION NOT NULL,
  tax_cents_kwh DOUBLE PRECISION NOT NULL,
  vat_percent DOUBLE PRECISION NOT NULL,
  night_start_hour INTEGER NOT NULL CHECK (night_start_hour BETWEEN 0 AND 23),
  night_end_hour INTEGER NOT NULL CHECK (night_end_hour BETWEEN 0 AND 23),
  PRIMARY KEY (user_id, valid_from)
);

-- The terms of each user apply from the start. The term columns of
-- user_settings stay, because the release before this migration reads them.
INSERT INTO contract_terms
  (user_id, valid_from, margin_cents_kwh, transfer_day_cents_kwh, transfer_night_cents_kwh,
   tax_cents_kwh, vat_percent, night_start_hour, night_end_hour)
SELECT user_id, DATE '1970-01-01', margin_cents_kwh, transfer_day_cents_kwh,
       transfer_night_cents_kwh, tax_cents_kwh, vat_percent, night_start_hour, night_end_hour
FROM user_settings;
